// engineCatalogue.ts — the modules the ENGINE provides, read from its plugin scan
// (`~/.studio/exts.json`) rather than from files.
//
// This replaces a folder of generated wrappers. `module populate` used to write one
// `module.yaml` per scanned plugin, each containing exactly two facts — `plugin.type` and
// `plugin.name` — into the workspace's `_modules`. The scan they were copied FROM carries
// the format, the manufacturer, the role and the category, so the copy was strictly less
// informed than its source, had to be regenerated by hand, and went stale in silence.
//
// So the catalogue is READ, not written. `_modules` keeps only what someone authored: a
// jsdsp module's source, a rack's sample map — modules that are something on disk.
//
// A leaf: nothing here imports beyond the pure vocabulary in moduleTypes.ts, so loader.ts
// can use it without a cycle. It reads a machine-local file under `~/.studio`, exactly
// as preferences.ts already does.

import { existsSync, readFileSync, statSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import {
  categoryForRole,
  ENGINE_NS,
  engineModuleOf,
  engineRef,
  MODULE_TYPES,
  slugifyPluginName,
} from "./moduleTypes";
import type { LoadedModule } from "./rawDoc";

/** The scan cache. CONTRACT path — the C++ engine writes and reads this same file (PluginScan.cpp `extsCacheFile()`). */
export const EXTS_PATH = join(homedir(), ".studio", "exts.json");

/** One plugin as the engine's scan describes it. `format` is as scanned ("VST3", "internal"). */
export interface ScannedPlugin {
  name: string;
  format: string;
  manufacturer?: string;
  role?: string; // "instrument" | "audioEffect" | "midiEffect"
  instrument?: boolean;
  category?: string; // the plugin's own, e.g. "Fx|Delay" or "instrument|synth"
}

// Memoised per FILE: the machine's cache is read on the graph's hot path, and a test
// points at a fixture instead — one cache would make the two evict each other.
const memo = new Map<string, { stamp: string; plugins: ScannedPlugin[] }>();

/**
 * Every scanned plugin, memoised on the cache file's mtime+size.
 *
 * EMPTY means "we cannot say", not "nothing is installed" — a machine that has never run
 * a scan, or a corrupt file, both land here, and a caller that read it as "installed:
 * none" would paint every plugin in every project as missing.
 */
export function scannedPlugins(file = EXTS_PATH): ScannedPlugin[] {
  if (!existsSync(file)) return [];
  let stamp: string;
  try {
    const st = statSync(file);
    stamp = `${st.mtimeMs}:${st.size}`;
  } catch {
    return [];
  }
  const hit = memo.get(file);
  if (hit && hit.stamp === stamp) return hit.plugins;
  const plugins: ScannedPlugin[] = [];
  try {
    const root = JSON.parse(readFileSync(file, "utf8"));
    for (const e of root.entries ?? [])
      for (const p of e.plugins ?? []) {
        if (!p?.name || !p?.format) continue;
        plugins.push({
          name: String(p.name),
          format: String(p.format),
          manufacturer: p.manufacturer ? String(p.manufacturer) : undefined,
          role: p.role ? String(p.role) : undefined,
          instrument: p.instrument === true,
          category: p.category ? String(p.category) : undefined,
        });
      }
  } catch {
    return []; // a corrupt cache reads as "unknown", not as "empty"
  }
  // Sorted so a map built from this is stable across runs — the order the scan happened
  // to write is not something a project's refs should depend on.
  plugins.sort(
    (a, b) => a.name.localeCompare(b.name) || a.format.localeCompare(b.format),
  );
  memo.set(file, { stamp, plugins });
  return plugins;
}

// "<format>|<name>", both lowercased — the engine's iequals(format) && iequals(name) match.
const scanKey = (format: string, name: string): string =>
  `${format.toLowerCase()}|${name.toLowerCase()}`;

/** Every scanned plugin as a "<format>|<name>" key set (both lowercased). Empty ⇒ "unknown" (see scannedPlugins). */
export function scannedPluginKeys(file = EXTS_PATH): Set<string> {
  return new Set(scannedPlugins(file).map((p) => scanKey(p.format, p.name)));
}

/**
 * Does the engine know this external plugin? `format` is the authored plugin.type
 * ("vst3", "au", …) and `name` the plugin's real name. False only when the cache is
 * non-empty and the pair is absent, so a machine that has never scanned answers true.
 */
export function isPluginScanned(
  format: string,
  name: string,
  file = EXTS_PATH,
): boolean {
  const keys = scannedPluginKeys(file);
  if (!keys.size) return true; // no cache to judge against
  return keys.has(scanKey(format, name));
}

/** Scanned plugin names grouped by lowercased format — `{ vst3: ["Serum"], internal: […] }`. */
export function scannedPluginNames(file = EXTS_PATH): Record<string, string[]> {
  const names: Record<string, string[]> = {};
  for (const p of scannedPlugins(file))
    (names[p.format.toLowerCase()] ??= []).push(p.name);
  return names;
}

// The ref vocabulary moved to moduleTypes.ts — the leaf with no filesystem — so a BROWSER can name an
// engine module without pulling this file's `node:fs` in behind it (see engineFace.ts, which does).
// Re-exported because this is where every existing caller already looks for it.
export { ENGINE_NS, engineRef };

/**
 * The io modules the engine provides. One IN and one OUT for the whole app — a project
 * makes instances of them, and those carry the channel, the monitoring and the trim.
 *
 * They were files in `_modules` too, one folder plus one instance per interface channel,
 * written by `module populate` from the machine's preferences. That put a rig's wiring in
 * a library shared by every song; the instances belong to the song that records through
 * them.
 */
const IO_MODULES: Record<string, { io: "in" | "out" | "file" }> = {
  IN: { io: "in" },
  OUT: { io: "out" },
  // The file source: audio off disk rather than off an interface. One module, like the other
  // two, and an instance carries WHICH file — or carries none, in a chain template, where the
  // audio belongs to whatever the template is applied to. See docs/fileInput.md.
  FILE: { io: "file" },
};

/**
 * Every module the engine offers, keyed by ref — the scanned plugins plus IN and OUT.
 *
 * `plugin.type` is the scanned FORMAT, lowercased, and nothing else. `module populate`
 * wrote `internal` whenever the role was "instrument", which mislabelled all forty VST3
 * instruments on this machine — a wrapper for one claimed to be a built-in, and the engine
 * would have gone looking for a built-in by that name. Nothing hit it because the projects
 * that use those plugins declare them inline; the rule is simply wrong, and this is the
 * one place it is now stated.
 */
export function engineModules(file = EXTS_PATH): Record<string, LoadedModule> {
  const out: Record<string, LoadedModule> = {};
  for (const [name, { io }] of Object.entries(IO_MODULES))
    out[engineRef(name)] = {
      io,
      kind: MODULE_TYPES.io.kind,
      inputs: MODULE_TYPES.io.inputs,
      category: "io",
      file: name,
    };
  for (const p of scannedPlugins(file)) {
    // The ref and the plugin block come from moduleTypes, which is also what the médiathèque's
    // browser applies to the scan reported over the socket — one rule, so the two cannot spell
    // the same plugin differently.
    const named = engineModuleOf(p);
    if (!named) continue;
    const { ref, plugin } = named;
    if (out[ref]) continue; // first wins — two scans of one plugin collapse to one module
    const category = categoryForRole(p);
    const meta = MODULE_TYPES[category];
    out[ref] = {
      plugin,
      kind: meta.kind,
      // The type's defaults, and only those: a SCANNED plugin has no file to declare ports in.
      // What it really offers is the plugin's business, and the engine is what would know.
      inputs: meta.inputs,
      outputs: meta.outputs,
      category,
      file: slugifyPluginName(p.name),
    };
  }
  return out;
}
